document.addEventListener('DOMContentLoaded', function() {
  var galleries = [
    { cls: 'aliados_carusel', forward: true }
  ];

  galleries.forEach(function(g) {
    var wrapperSelector = '.' + g.cls + ' .elementor-image-carousel-wrapper';
    var container = document.querySelector(wrapperSelector);
    if (!container) return;
    var track = container.querySelector('.swiper-wrapper');
    if (!track) return;

    var originals = Array.from(track.children).filter(function(slide) {
      return slide.classList.contains('swiper-slide') &&
             !slide.classList.contains('swiper-slide-duplicate');
    });
    track.innerHTML = '';

    var w = window.innerWidth;
    var repeatCount = w <= 768 ? 3 : (w <= 1024 ? 3 : 8); 

    for (var i = 0; i < repeatCount; i++) {
      originals.forEach(function(slide) {
        track.appendChild(slide.cloneNode(true));
      });
    }

    // --- layout e espaçamento ---
    track.style.display      = 'flex';
    track.style.flexWrap     = 'nowrap';
    container.style.overflow = 'hidden';

    var items = w <= 768 ? 2 : (w <= 1024 ? 3 : (w <= 1920 ? 4 : 5));
    var basis = (100 / items) + '%';
    track.querySelectorAll('.swiper-slide').forEach(function(slide) {
      slide.style.flex = '0 0 ' + basis;
    });

    // --- animação ---
    var name      = g.forward ? 'pureMarquee' : 'reversePureMarquee';
    var from      = g.forward ? '0'    : '-50%';
    var to        = g.forward ? '-50%' : '0';
    var duration  = w <= 768 ? 08 : 25; // tempo ajustado no mobile

    var styleTag = document.createElement('style');
    styleTag.textContent = `
      @keyframes ${name} {
        0%   { transform: translateX(${from}); }
        100% { transform: translateX(${to});   }
      }
      .${g.cls} .swiper-wrapper {
        animation: ${name} ${duration}s linear infinite;
      }
    `;
    document.head.appendChild(styleTag);

    // --- fade de inicialização ---
    document.querySelector('.' + g.cls).classList.add('initialized');
  });
});
